Here is the commit message:
kasan: fix unaligned address is unhandled in
 kasan_remove_zero_shadow

During testing kasan_populate_early_shadow and kasan_remove_zero_shadow,
if the shadow start and end address in kasan_remove_zero_shadow() is not
aligned to PMD_SIZE, the remain unaligned PTE won't be removed.

In the test case for kasan_remove_zero_shadow():

    shadow_start: 0xffffffb802000000, shadow end: 0xffffffbfbe000000

    3-level page table:
      PUD_SIZE: 0x40000000 PMD_SIZE: 0x200000 PAGE_SIZE: 4K

0xffffffbf80000000 ~ 0xffffffbfbdf80000 will not be removed because in
kasan_remove_pud_table(), kasan_pmd_table(*pud) is true but the next
address is 0xffffffbfbdf80000 which is not aligned to PUD_SIZE.

In the correct condition, this should fallback to the next level
kasan_remove_pmd_table() but the condition flow always continue to skip
the unaligned part.

Fix by correcting the condition when next and addr are neither aligned.

Link: https://lkml.kernel.org/r/20210103135621.83129-1-lecopzer@gmail.com
Fixes: 0207df4fa1a86 ("kernel/memremap, kasan: make ZONE_DEVICE with work with KASAN")
Signed-off-by: Lecopzer Chen <lecopzer.chen@mediatek.com>
Cc: Andrey Ryabinin <aryabinin@virtuozzo.com>
Cc: Dan Williams <dan.j.williams@intel.com>
Cc: Dmitry Vyukov <dvyukov@google.com>
Cc: Alexander Potapenko <glider@google.com>
Cc: YJ Chiang <yj.chiang@mediatek.com>
Cc: Andrey Konovalov <andreyknvl@google.com>
Signed-off-by: Andrew Morton <akpm@linux-foundation.org>
Signed-off-by: Linus Torvalds <torvalds@linux-foundation.org>

Here is the root cause:
The bug occurs because the conditions in the functions responsible for removing page table entries (PTEs) do not properly handle cases where the addresses are unaligned to the respective page size (PMD_SIZE, PUD_SIZE, P4D_SIZE, PGDIR_SIZE). As a result, when the shadow start and end addresses are not aligned, the code fails to clear the corresponding entries in the page tables, leading to unhandled unaligned addresses.

Here is the patch:

 static void kasan_remove_pmd_table(pmd_t *pmd, unsigned long addr,
 				unsigned long end)
 {
 	unsigned long next;

 	for (; addr < end; addr = next, pmd++) {
 		pte_t *pte;

 		next = pmd_addr_end(addr, end);

 		if (!pmd_present(*pmd))
 			continue;

 		if (kasan_pte_table(*pmd)) {
 			if (IS_ALIGNED(addr, PMD_SIZE) &&
-			    IS_ALIGNED(next, PMD_SIZE))
+			    IS_ALIGNED(next, PMD_SIZE)) {
 				pmd_clear(pmd);
-			continue;
+				continue;
+			}
 		}
 		pte = pte_offset_kernel(pmd, addr);
 		kasan_remove_pte_table(pte, addr, next);
 		kasan_free_pte(pte_offset_kernel(pmd, 0), pmd);
 	}
 }

 static void kasan_remove_pud_table(pud_t *pud, unsigned long addr,
 				unsigned long end)
 {
 	unsigned long next;

 	for (; addr < end; addr = next, pud++) {
 		pmd_t *pmd, *pmd_base;

 		next = pud_addr_end(addr, end);

 		if (!pud_present(*pud))
 			continue;

 		if (kasan_pmd_table(*pud)) {
 			if (IS_ALIGNED(addr, PUD_SIZE) &&
-			    IS_ALIGNED(next, PUD_SIZE))
+			    IS_ALIGNED(next, PUD_SIZE)) {
 				pud_clear(pud);
-			continue;
+				continue;
+			}
 		}
 		pmd = pmd_offset(pud, addr);
 		pmd_base = pmd_offset(pud, 0);
 		kasan_remove_pmd_table(pmd, addr, next);
 		kasan_free_pmd(pmd_base, pud);
 	}
 }

 static void kasan_remove_p4d_table(p4d_t *p4d, unsigned long addr,
 				unsigned long end)
 {
 	unsigned long next;

 	for (; addr < end; addr = next, p4d++) {
 		pud_t *pud;

 		next = p4d_addr_end(addr, end);

 		if (!p4d_present(*p4d))
 			continue;

 		if (kasan_pud_table(*p4d)) {
 			if (IS_ALIGNED(addr, P4D_SIZE) &&
-			    IS_ALIGNED(next, P4D_SIZE))
+			    IS_ALIGNED(next, P4D_SIZE)) {
 				p4d_clear(p4d);
-			continue;
+				continue;
+			}
 		}
 		pud = pud_offset(p4d, addr);
 		kasan_remove_pud_table(pud, addr, next);
 		kasan_free_pud(pud_offset(p4d, 0), p4d);
 	}
 }

 void kasan_remove_zero_shadow(void *start, unsigned long size)
 {
 	unsigned long addr, end, next;
 	pgd_t *pgd;

 	addr = (unsigned long)kasan_mem_to_shadow(start);
 	end = addr + (size >> KASAN_SHADOW_SCALE_SHIFT);

 	if (WARN_ON((unsigned long)start % KASAN_MEMORY_PER_SHADOW_PAGE) ||
 	    WARN_ON(size % KASAN_MEMORY_PER_SHADOW_PAGE))
 		return;

 	for (; addr < end; addr = next) {
 		p4d_t *p4d;

 		next = pgd_addr_end(addr, end);

 		pgd = pgd_offset_k(addr);
 		if (!pgd_present(*pgd))
 			continue;

 		if (kasan_p4d_table(*pgd)) {
 			if (IS_ALIGNED(addr, PGDIR_SIZE) &&
-			    IS_ALIGNED(next, PGDIR_SIZE))
+			    IS_ALIGNED(next, PGDIR_SIZE)) {
 				pgd_clear(pgd);
-			continue;
+				continue;
+			}
 		}

 		p4d = p4d_offset(pgd, addr);
 		kasan_remove_p4d_table(p4d, addr, next);
 		kasan_free_p4d(p4d_offset(pgd, 0), pgd);
 	}
 }



